shellCommands.command:
PORT=3456 node server.js & sleep 1; curl -s -o /dev/null -w "home: %{http_code}
" localhost:3456/; curl -s -o /dev/null -w "add: %{http_code} -> %{redirect_url}
" -d "title=The Left Hand of Darkness&author=Ursula K. Le Guin&notes=Winter planet" localhost:3456/books; ID=$(curl -s localhost:3456/ | grep -o 'books/[a-f0-9]*' | head -1 | cut -d/ -f2); curl -s -o /dev/null -w "share link: %{http_code}
" localhost:3456/books/$ID; curl -s -o /dev/null -w "finish: %{http_code}
" -X POST localhost:3456/books/$ID/finish; curl -s localhost:3456/ | grep -c 'id="finished"'; kill %1; rm -f books.json
